/** Paths the code's own pages and the server hold: no CMS page may take one. */
export const RESERVED = [
  "/account/",
  "/login/",
  "/register/",
  "/forgot-password/",
  "/unsubscribe/",
  "/legal/",
  "/app/",
  "/admin/",
  "/v1/",
  "/cms-api/",
  "/_next/",
  "/art/",
  "/__cms__/",
] as const;

/** Whether [path] is a page's address: "/", or segments of lower-case letters, digits and hyphens, with slashes round them. */
export const isPagePath = (path: string) =>
  path === "/" || (/^\/([a-z0-9]+(-[a-z0-9]+)*\/)+$/.test(path) && !RESERVED.some((r) => path.startsWith(r)));

/** Flat message keys ("nav.signIn") back into next-intl's nesting, in [locale]. */
export function textsAsMessages(texts: Record<string, L10n>, locale: string) {
  const out: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(texts)) {
    const parts = key.split(".");
    let at = out;
    for (const p of parts.slice(0, -1)) at = (at[p] ??= {}) as Record<string, unknown>;
    const text = pick(value, locale);
    if (text) at[parts.at(-1)!] = text;
  }
  return out;
}

/** [over] laid on [base], nested objects merged. */
export function deepMerge<T extends Record<string, unknown>>(base: T, over: Record<string, unknown>): T {
  const out: Record<string, unknown> = { ...base };
  for (const [k, v] of Object.entries(over)) {
    const b = out[k];
    out[k] =
      v && typeof v === "object" && !Array.isArray(v) && b && typeof b === "object" && !Array.isArray(b)
        ? deepMerge(b as Record<string, unknown>, v as Record<string, unknown>)
        : v;
  }
  return out as T;
}
